import{_ as r,C as s,o as a,c as l,a2 as o,b as p,w as e,a as u,E as d,a3 as i}from"./chunks/framework.BC3NdntU.js";const _=JSON.parse('{"title":"11.1 从 LLM 到 Agent:底层心智","description":"","frontmatter":{},"headers":[],"relativePath":"卷十一-AIAgentHarness与提示词工程/11.1-从LLM到Agent底层心智.md","filePath":"卷十一-AIAgentHarness与提示词工程/11.1-从LLM到Agent底层心智.md","lastUpdated":1788947714000}'),h={name:"卷十一-AIAgentHarness与提示词工程/11.1-从LLM到Agent底层心智.md"};function q(c,t,g,b,m,A){const n=s("Mermaid");return a(),l("div",null,[t[1]||(t[1]=o('<h1 id="_11-1-从-llm-到-agent-底层心智" tabindex="-1">11.1 从 LLM 到 Agent:底层心智 <a class="header-anchor" href="#_11-1-从-llm-到-agent-底层心智" aria-label="Permalink to &quot;11.1 从 LLM 到 Agent:底层心智&quot;">​</a></h1><h2 id="引言-先放下-ai-会思考-的直觉-回到一个反直觉的事实" tabindex="-1">引言:先放下&quot;AI 会思考&quot;的直觉,回到一个反直觉的事实 <a class="header-anchor" href="#引言-先放下-ai-会思考-的直觉-回到一个反直觉的事实" aria-label="Permalink to &quot;引言:先放下&quot;AI 会思考&quot;的直觉,回到一个反直觉的事实&quot;">​</a></h2><p>理解 Agent、Harness、提示词工程的一切,要从一个反直觉事实出发:<strong>大语言模型(LLM)的本质不是&quot;回答问题&quot;,而是&quot;预测下一个 token&quot;</strong>。这一章把这个底层心智立住,后面七章全建立在此之上。</p><hr><h2 id="一、llm-的本质-自回归的-下一词预测器" tabindex="-1">一、LLM 的本质:自回归的&quot;下一词预测器&quot; <a class="header-anchor" href="#一、llm-的本质-自回归的-下一词预测器" aria-label="Permalink to &quot;一、LLM 的本质:自回归的&quot;下一词预测器&quot;&quot;">​</a></h2><p>LLM 数学上只做一件事:</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>输入文本(context)→ 输出&quot;下一个 token 的概率分布&quot;→ 采样一个</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>反复执行(把生成的 token 追加回上下文),就是<strong>自回归(autoregressive)</strong>。</p><p><strong>为什么&quot;预测下一个词&quot;能显得&quot;智能&quot;?</strong> 预训练在海量文本上学&quot;给定上文,什么词最可能出现&quot;。语料足够大时,这种条件概率里<strong>被压缩进了大量世界知识、语法、逻辑、常识</strong>——因为要预测好&quot;下个词&quot;,就必须&quot;隐式理解&quot;上文。所以&quot;补全&quot;和&quot;理解&quot;是一体两面。</p><hr><h2 id="二、采样-为什么同样-prompt-有不同答案" tabindex="-1">二、采样:为什么同样 prompt 有不同答案 <a class="header-anchor" href="#二、采样-为什么同样-prompt-有不同答案" aria-label="Permalink to &quot;二、采样:为什么同样 prompt 有不同答案&quot;">​</a></h2><table tabindex="0"><thead><tr><th>参数</th><th>作用</th><th>影响</th></tr></thead><tbody><tr><td><code>temperature</code></td><td>分布陡/平</td><td>低=确定保守,高=发散创意</td></tr><tr><td><code>top_p</code></td><td>只从累积概率前 N 采</td><td>收窄候选</td></tr><tr><td><code>top_k</code></td><td>只取概率前 K</td><td>硬截断</td></tr></tbody></table><blockquote><p>工程启示:要稳定可复现(代码/格式)→ 低温甚至 0;要多样创意(文案/头脑风暴)→ 调高。</p></blockquote><hr><h2 id="三、两个关键行为特性" tabindex="-1">三、两个关键行为特性 <a class="header-anchor" href="#三、两个关键行为特性" aria-label="Permalink to &quot;三、两个关键行为特性&quot;">​</a></h2><h3 id="_1-上下文学习-icl" tabindex="-1">1. 上下文学习(ICL) <a class="header-anchor" href="#_1-上下文学习-icl" aria-label="Permalink to &quot;1. 上下文学习(ICL)&quot;">​</a></h3><p>不更新权重就学会新任务,靠 prompt 里<strong>给示例(few-shot)</strong>。这就是&quot;提示词即编程&quot;的根源。</p><h3 id="_2-幻觉-hallucination" tabindex="-1">2. 幻觉(Hallucination) <a class="header-anchor" href="#_2-幻觉-hallucination" aria-label="Permalink to &quot;2. 幻觉(Hallucination)&quot;">​</a></h3><p>模型用概率补全,不是查数据库,会自信地编造事实。</p><blockquote><p><strong>工程启示:一切外部事实靠工具/检索锚定,不靠模型&quot;记忆&quot;——Agent 工程第一铁律。</strong></p></blockquote><hr><h2 id="四、从-聊天-到-agent-的心智跃迁" tabindex="-1">四、从&quot;聊天&quot;到&quot;Agent&quot;的心智跃迁 <a class="header-anchor" href="#四、从-聊天-到-agent-的心智跃迁" aria-label="Permalink to &quot;四、从&quot;聊天&quot;到&quot;Agent&quot;的心智跃迁&quot;">​</a></h2>',22)),(a(),p(i,null,{default:e(()=>[d(n,{id:"mermaid-107",class:"mermaid",graph:"flowchart%20LR%0A%20%20%20%20A%5BLLM%3Cbr%2F%3E%E9%A2%84%E6%B5%8B%E4%B8%8B%E4%B8%80%E8%AF%8D%5D%20--%3E%20B%5BHarness%20%E8%BF%90%E8%A1%8C%E6%97%B6%E5%BE%AA%E7%8E%AF%5D%0A%20%20%20%20B%20--%3E%20C%5BPrompt%20%E6%96%B9%E5%90%91%5D%0A%20%20%20%20B%20--%3E%20D%5BTools%20%E6%89%8B%E8%84%9A%5D%0A%20%20%20%20B%20--%3E%20E%5BContext%20%E8%AE%B0%E5%BF%86%5D%0A%20%20%20%20C%20%26%20D%20%26%20E%20--%3E%20F%5BAgent%3Cbr%2F%3E%E8%A7%82%E5%AF%9F-%E6%80%9D%E8%80%83-%E8%A1%8C%E5%8A%A8%5D%0A"})]),fallback:e(()=>[...t[0]||(t[0]=[u(" Loading... ",-1)])]),_:1})),t[2]||(t[2]=o(`<p><strong>贯穿全卷的比喻:</strong></p><blockquote><ul><li>LLM = 发动机;Prompt = 方向盘;Tools = 手脚;Context = 记忆;Harness = 车身 + 车手(把一切串成循环)</li></ul></blockquote><p><strong>没有 Harness,LLM 就是一次性的&quot;文本补全函数&quot;;有了 Harness,才成为能千步循环、调用工具、自我纠错的 Agent。</strong></p><hr><h2 id="五、llm-的能力边界" tabindex="-1">五、LLM 的能力边界 <a class="header-anchor" href="#五、llm-的能力边界" aria-label="Permalink to &quot;五、LLM 的能力边界&quot;">​</a></h2><table tabindex="0"><thead><tr><th>边界</th><th>化解</th></tr></thead><tbody><tr><td>上下文窗口有限</td><td>记忆压缩/检索(11.4)</td></tr><tr><td>知识有截止</td><td>工具检索实时数据</td></tr><tr><td>单次无状态</td><td>harness 持久化上下文</td></tr><tr><td>非确定性</td><td>低温 + 约束格式 + 重试</td></tr><tr><td>不能真正执行</td><td>tools 把文本指向真实动作</td></tr></tbody></table><hr><h2 id="六、小结" tabindex="-1">六、小结 <a class="header-anchor" href="#六、小结" aria-label="Permalink to &quot;六、小结&quot;">​</a></h2><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>LLM 本质 = 自回归 next-token 预测 + 采样(temperature/top_p)</span></span>
<span class="line"><span>智能来源 = 预训练把知识压缩进条件概率 → 涌现 + 上下文学习</span></span>
<span class="line"><span>关键特性:ICL(提示词即编程)、幻觉(概率补全≠查库)</span></span>
<span class="line"><span>Agent = LLM + Prompt + Tools + Context + Harness(循环)</span></span>
<span class="line"><span>铁律:外部事实靠工具/检索锚定;稳定靠低温+格式约束</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><hr><h2 id="七、思考题-自测理解" tabindex="-1">七、思考题(自测理解) <a class="header-anchor" href="#七、思考题-自测理解" aria-label="Permalink to &quot;七、思考题(自测理解)&quot;">​</a></h2><p><strong>Q1:为什么说&quot;LLM 会补全&quot;和&quot;LLM 会理解&quot;是同一件事?</strong></p><p>要<strong>预测好下一个 token</strong>,模型必须在权重里学出对上下文的<strong>深层理解</strong>(语法、逻辑、世界知识)。&quot;补全&quot;是表面动作,&quot;理解&quot;是达成补全所必需的隐式能力,一体两面。</p><p><strong>Q2:如何让&quot;只会下一词预测&quot;的模型执行&quot;查天气并写进文件&quot;?</strong></p><p>① 模型输出结构化&quot;动作&quot;(如 <code>get_weather(city)</code>);② harness 解析并<strong>真执行工具</strong>;③ 结果作为新上下文喂回;④ 循环直到&quot;完成&quot;。模型负责决策,工具/harness 负责执行。</p><p><strong>Q3:temperature 对输出有什么影响?什么时候用低温?</strong></p><p>temperature 控制采样分布的&quot;陡峭度&quot;:<strong>低</strong>→ 候选集中、确定保守(代码生成、格式化输出、事实问答);<strong>高</strong>→ 候选发散、多样创意(文案、头脑风暴)。要稳定可复现用低温(甚至 0)。</p><p><strong>Q4:上下文学习(ICL)和微调(FT)的本质区别?</strong></p><p>ICL <strong>不更新权重</strong>,只在 prompt 里给示例,即学即用、零训练成本但受窗口限制;FT <strong>更新权重</strong>,需数据与算力,能持久固化能力但成本高。ICL 是&quot;提示词工程&quot;能成立的根本。</p><p><strong>Q5:LLM 的&quot;幻觉&quot;根源是什么?工程上如何缓解?</strong></p><p>根源:模型是<strong>概率补全</strong>,不是查库,且缺乏&quot;我不知道&quot;的强概念。缓解:① 外部事实靠<strong>工具/检索(RAG)锚定</strong>;② 约束输出格式 + 低温;③ &quot;不知道就说不知道&quot;(负面约束,11.6);④ 关键结果人工核验。</p><p><strong>Q6:Agent 相比&quot;单次 LLM 调用&quot;多了哪几样东西?</strong></p><p>多了 <strong>Tools(能行动)、Context(有记忆)、循环(能观察-思考-行动多轮)</strong> 三者,由 Harness 串起来。单次调用只有&quot;一次文本补全&quot;,Agent 是&quot;多轮、有手脚、有记忆的任务执行系统&quot;。</p><hr><p>📎 参考:<a href="https://www.anthropic.com/" target="_blank" rel="noreferrer">Anthropic</a>《Building Effective Agents》、<a href="https://platform.openai.com/docs" target="_blank" rel="noreferrer">OpenAI 文档</a>、Attention Is All You Need 与 RLHF 相关论文</p>`,25))])}const E=r(h,[["render",q]]);export{_ as __pageData,E as default};
